type item struct{ d, v int }
type PQ []item

func (p PQ) Len() int           { return len(p) }
func (p PQ) Less(i, j int) bool { return p[i].d > p[j].d }
func (p PQ) Swap(i, j int)      { p[i], p[j] = p[j], p[i] }
func (p *PQ) Push(x any)        { *p = append(*p, x.(item)) }
func (p *PQ) Pop() any {
    o := *p
    x := o[len(o)-1]
    *p = o[:len(o)-1]
    return x
}

