func dijkstra(g [][]item, n int) int {
    dist := make([]int, n+1)
    st := make([]bool, n+1)
    for i := range dist {
        dist[i] = 1 << 60
    }
    dist[1] = 0
    pq := &PQ{{0, 1}}
    for pq.Len() > 0 {
        cur := heap.Pop(pq).(item)
        if st[cur.v] {
            continue
        }
        st[cur.v] = true
        for _, e := range g[cur.v] {
            if dist[cur.v]+e.d < dist[e.v] {
                dist[e.v] = dist[cur.v] + e.d
                heap.Push(pq, item{dist[e.v], e.v})
            }
        }
    }
    if dist[n] == 1<<60 {
        return -1
    }
    return dist[n]
