func main() {
    in := bufio.NewReader(os.Stdin)
    var n int
    fmt.Fscan(in, &n)
    tails := []int{}
    for i := 0; i < n; i++ {
        var x int
        fmt.Fscan(in, &x)
        p := sort.SearchInts(tails, x)
        if p == len(tails) {
            tails = append(tails, x)
        } else {
            tails[p] = x
        }
    }
    fmt.Println(len(tails))
}
